// Original proofs. Restricted statements are labelled explicitly; note records the boundary.
const step=(claim,reason,uses=[])=>({claim,reason,...(uses.length?{uses}:{})});
const proof=(id,chapter,title,statement,assumptions,theoryTopic,prerequisites,steps,conclusion,note)=>({id:'y2-'+id,chapter,title,statement,assumptions,theoryTopic,prerequisites:prerequisites.map(([chapter,topic])=>({chapter,topic})),steps,conclusion,...(note?{note}:{})});
export const SECOND_YEAR_PROOFS=[
proof('uniform-continuity','five','Непрерывность равномерного предела','Равномерный предел непрерывных функций непрерывен.', ['fₙ непрерывны на метрическом пространстве E.','fₙ⇒f на E.'],"Непрерывность и интегрирование предела",[["five", "Поточечная и равномерная сходимость"], ["limits", "Определение непрерывности"], ["space", "Норма и скалярное произведение"]],[
step('Зафиксируем a∈E и ε>0. Выберем n с sup_E|fₙ−f|<ε/3.','Равномерная сходимость даёт оценку сразу во всех точках; выбранный n дальше не меняется.'),
step('Существует δ>0: d(x,a)<δ ⇒ |fₙ(x)−fₙ(a)|<ε/3.','Используется непрерывность одной выбранной функции fₙ в a.'),
step('|f(x)−f(a)|≤|f(x)−fₙ(x)|+|fₙ(x)−fₙ(a)|+|fₙ(a)−f(a)|.','Прибавили и вычли fₙ(x), fₙ(a), затем применили неравенство треугольника.'),
step('При d(x,a)<δ правая часть меньше ε.','Каждое из трёх слагаемых меньше ε/3. Это определение непрерывности f в произвольной точке a.')], 'f непрерывна на E.'),
proof('uniform-integral','five','Интегрирование равномерного предела','Если интегрируемые по Риману fₙ⇒f на [a,b], то f интегрируема и ∫fₙ→∫f.', ['a<b конечны.','Все fₙ интегрируемы по Риману; сходимость равномерная.'],"Непрерывность и интегрирование предела",[["five", "Поточечная и равномерная сходимость"], ["three", "Критерий Дарбу и достаточные условия"], ["three", "Верхний и нижний интегралы Дарбу"], ["three", "Линейность, аддитивность и операции"]],[
step('Обозначим ηₙ=sup|fₙ−f|; ηₙ→0. Функция f ограниченна.','Для достаточно большого n функция f отличается от ограниченной fₙ не более чем на конечное ηₙ.'),
step('Для любого разбиения P разность сумм Дарбу f не превосходит U(fₙ,P)−L(fₙ,P)+2ηₙ(b−a).','На каждом подотрезке sup f≤sup fₙ+ηₙ и inf f≥inf fₙ−ηₙ.'),
step('Сначала выбираем n, затем P так, чтобы оба слагаемых были меньше ε/2.','Равномерная сходимость контролирует второе слагаемое, интегрируемость fₙ — первое. Критерий Дарбу доказывает интегрируемость f.'),
step('|∫fₙ−∫f|≤∫|fₙ−f|≤(b−a)ηₙ→0.','Линейность, монотонность интеграла и общая оценка разности дают требуемый предел.')], 'Предельный переход под интегралом обоснован.'),
proof('mtest','five','Признак Вейерштрасса для функционального ряда','Если |uₙ(x)|≤Mₙ и ΣMₙ<∞, ряд Σuₙ сходится равномерно.', ['Mₙ≥0.','Одна оценка |uₙ(x)|≤Mₙ действует для всех x∈E.'],"Функциональный ряд и признак Вейерштрасса",[["five", "Поточечная и равномерная сходимость"], ["numeric", "Положительные ряды и сравнение"], ["numeric", "Абсолютная и условная сходимость"]],[
step('Для каждого x числовой ряд Σ|uₙ(x)| сходится.','Он мажорируется сходящимся рядом неотрицательных чисел ΣMₙ.'),
step('Положим S(x)=Σuₙ(x). Для m>n имеем |Σₖ₌ₙ₊₁ᵐuₖ(x)|≤Σₖ₌ₙ₊₁ᵐMₖ.','Это неравенство треугольника для конечной суммы.'),
step('|S(x)−Sₙ(x)|≤Σₖ>ₙMₖ для каждого x.','Переходим к пределу m→∞ в предыдущем числовом неравенстве.'),
step('sup_E|S−Sₙ|≤Σₖ>ₙMₖ→0.','Правая часть не зависит от x и является хвостом сходящегося числового ряда.')], 'Сходимость ряда равномерна и поточечно абсолютна.'),
proof('derivative-limit','five','Дифференцирование предела','Если fₙ∈C¹[a,b], fₙ(a) сходится и fₙ′⇒g, то fₙ⇒f∈C¹ и f′=g.', ['[a,b] — конечный отрезок.','Равномерная сходимость производных действует на всём отрезке.'],"Дифференцирование предела",[["five", "Поточечная и равномерная сходимость"], ["five", "Непрерывность и интегрирование предела"], ["three", "Основная теорема и формула Ньютона — Лейбница"], ["derivatives", "Высшие производные и формула Лейбница"]],[
step('g непрерывна.','Она является равномерным пределом непрерывных fₙ′.',['y2-uniform-continuity']),
step('fₙ(x)=fₙ(a)+∫ₐˣfₙ′(t)dt.','Формула Ньютона — Лейбница применима к C¹-функции.'),
step('Положим f(x)=lim fₙ(a)+∫ₐˣg(t)dt. Тогда sup|fₙ−f|≤|fₙ(a)−lim fₖ(a)|+(b−a)sup|fₙ′−g|→0.','Вычитаем две интегральные формулы и оцениваем интеграл модулем и длиной отрезка.'),
step('f′(x)=g(x).','Интеграл непрерывной g с переменным верхним пределом имеет производную g. На концах понимаются односторонние производные.')], 'Одна точка фиксирует константу; равномерная сходимость производных определяет производную предела.'),
proof('contraction','higher','Лемма о сжимающем отображении','Сжатие полного непустого метрического пространства имеет единственную неподвижную точку.', ['T:X→X.','d(Tx,Ty)≤q d(x,y), 0≤q<1.','X полно.'],"Сжатие и неподвижная точка",[["space", "Норма и скалярное произведение"], ["space", "Сходимость и фундаментальность в ℝⁿ"], ["sequences", "Фундаментальность и критерий Коши"]],[
step('Выберем x₀∈X и определим xₙ₊₁=T(xₙ). Тогда d(xₙ₊₁,xₙ)≤qⁿd(x₁,x₀).','Итерация условия сжатия уменьшает каждое последующее расстояние не более чем в q раз.'),
step('Для m>n расстояние d(xₘ,xₙ)≤qⁿd(x₁,x₀)/(1−q).','Складываем расстояния между соседними членами и оцениваем конечную геометрическую сумму бесконечной.'),
step('Последовательность фундаментальна и имеет предел x*.','Правая часть предыдущей оценки стремится к нулю независимо от m>n; полнота даёт предел в X.'),
step('T(x*)=x*.','Сжатие непрерывно, поэтому T(x*)=lim T(xₙ)=lim xₙ₊₁=x*.'),
step('Если T(y*)=y*, то d(x*,y*)≤q d(x*,y*), откуда d(x*,y*)=0.','Переносим q d(x*,y*) влево; коэффициент 1−q положителен.')], 'Неподвижная точка существует и единственна.'),
proof('euler','higher','Тождество Эйлера','Дифференцируемая однородная функция степени k удовлетворяет ∇f(x)·x=kf(x).', ['U — открытый конус в ℝⁿ.','f(tx)=tᵏf(x) при t>0; f дифференцируема.'],"Однородные функции и теорема Эйлера",[["four", "Градиент и производная по направлению"], ["higher", "Повторение: дифференциал и правило цепочки"]],[
step('Фиксируем x∈U и рассматриваем h(t)=f(tx).','Условие конуса гарантирует, что tx остаётся в области определения для всех t>0.'),
step('h′(t)=Df(tx)[x].','Правило цепочки: производная t↦tx есть вектор x.'),
step('С другой стороны, h(t)=tᵏf(x), поэтому h′(t)=ktᵏ⁻¹f(x).','При фиксированном x значение f(x) является константой по t.'),
step('При t=1 получаем Df(x)[x]=kf(x), то есть Σxᵢ∂ᵢf(x)=kf(x).','Дифференциал скалярной функции в евклидовых координатах равен скалярному произведению с градиентом.')], 'Тождество получается дифференцированием вдоль луча.'),
proof('inverse','higher','Локальная обратная функция: существование и производная','Для F∈C¹ с det DF(a)≠0 существует локальная C¹-обратная G, причём DG(F(x))=DF(x)⁻¹.', ['F определена на открытом U⊆ℝⁿ.','DF непрерывна и DF(a) обратима.'],"Теорема об обратном отображении",[["higher", "Повторение: дифференциал и правило цепочки"], ["higher", "Сжатие и неподвижная точка"], ["four", "Дифференциал векторного отображения"], ["continuity", "Линейные отображения и их норма"]],[
step('Заменами координат сводим a,F(a),DF(a) к 0,0,I. Выбираем r>0 и q<1 так, чтобы ‖DF(x)−I‖≤q на замкнутом шаре B̄_r⊂U.','Берём H(h)=DF(a)⁻¹(F(a+h)−F(a)); нужная оценка следует из непрерывности DH и DH(0)=I.'),
step('Для x,z∈B̄_r имеем ‖F(x)−F(z)−(x−z)‖≤q‖x−z‖.','Интегрируем производную F−id вдоль отрезка [z,x], который целиком лежит в выпуклом шаре.'),
step('При ‖y‖<(1−q)r отображение T_y(x)=x−F(x)+y является сжатием B̄_r в себя.','Предыдущая оценка даёт константу q; при z=0 получаем ‖T_y(x)‖≤q r+‖y‖<r. Полный замкнутый шар допускает единственную неподвижную точку G(y).',['y2-contraction']),
step('F(G(y))=y; G(y) лежит внутри шара, а ‖G(y)−G(v)‖≤‖y−v‖/(1−q).','Неподвижность равносильна F(x)=y. Нижняя оценка ‖F(x)−F(z)‖≥(1−q)‖x−z‖ даёт инъективность и липшицевость G.'),
step('Пусть x=G(y), h=G(y+k)−G(y). Тогда k=DF(x)h+o(‖h‖), а h=O(‖k‖).','Первое равенство — дифференцируемость F; второе — уже полученная липшицева оценка G.'),
step('Отсюда h=DF(x)⁻¹k+o(‖k‖); производная G непрерывна.','Матрица DF(x) обратима, поскольку ‖DF−I‖<1 (геометрический ряд даёт обратную). Непрерывность G, DF и обращения матриц даёт непрерывность DG.'),
step('Возвращаем исходные координаты и ограничиваем F на открытое множество F⁻¹(V)∩B_r.','Для малого открытого шара V значений найденный прообраз единственен и лежит в B_r; это действительно взаимно обратные отображения открытых окрестностей.')], 'Получена локальная C¹-обратимость, а не утверждение о глобальной инъективности.'),
proof('implicit','higher','Теорема о неявной функции','Если F(a,b)=0 и DᵧF(a,b) обратима, уравнение F(x,y)=0 локально задаёт C¹-функцию y=φ(x).', ['F:U⊆ℝⁿ×ℝᵐ→ℝᵐ класса C¹.','(a,b)∈U; det DᵧF(a,b)≠0.'],"Неявная функция и выпрямление",[["higher", "Повторение: дифференциал и правило цепочки"], ["higher", "Теорема об обратном отображении"], ["four", "Матрица Якоби и правило цепочки"]],[
step('Положим H(x,y)=(x,F(x,y)). Матрица DH имеет блоки [[I,0],[DₓF,DᵧF]].','Это непосредственное вычисление частных производных каждой группы компонент.'),
step('det DH(a,b)=det DᵧF(a,b)≠0, поэтому H локально имеет C¹-обратную.','Определитель блочно-треугольной матрицы равен произведению определителей диагональных блоков; применяется доказанная теорема.',['y2-inverse']),
step('Первая компонента H⁻¹(u,v) равна u. Запишем вторую как ψ(u,v) и положим φ(x)=ψ(x,0).','Равенство H(x,y)=(u,v) сразу даёт x=u. После уменьшения окрестности точки (a,0) все (x,0) допустимы.'),
step('F(x,y)=0 локально равносильно y=φ(x).','Уравнение H(x,y)=(x,0) имеет единственное локальное решение, заданное обратным H⁻¹.'),
step('DₓF+DᵧF·Dφ=0, значит Dφ=−(DᵧF)⁻¹DₓF вдоль графика.','Дифференцируем тождество F(x,φ(x))=0 по правилу цепочки. Обратимость блока сохраняется в достаточно малой окрестности по непрерывности.')], 'Неявная функция существует, единственна локально и имеет указанную производную.'),
proof('rank','higher','Теорема о постоянном ранге','C¹-отображение постоянного ранга r локально приводится к виду (u₁,…,uᵣ,0,…,0).', ['F:U⊆ℝⁿ→ℝᵐ класса C¹.','rank DF=r во всей окрестности a, а не только в a.'],"Постоянный ранг и функциональная зависимость",[["higher", "Теорема об обратном отображении"], ["continuity", "Линейные отображения и их норма"], ["continuity", "Матрица и композиция"]],[
step('При r=0 отображение локально постоянно: интеграл DF вдоль любого малого отрезка равен нулю. Далее считаем r>0 и переставляем координаты так, чтобы верхний левый r×r-минор DF(a) был ненулевым.','Определение ранга гарантирует ненулевой минор; перестановки координат являются линейными диффеоморфизмами.'),
step('H(x)=(F₁(x),…,Fᵣ(x),xᵣ₊₁,…,xₙ) локально обратимо.','Определитель DH равен выбранному ненулевому минору. Используется локальная обратимость.',['y2-inverse']),
step('В координатах (u,v)=H(x) имеем F∘H⁻¹(u,v)=(u,g(u,v)).','Первые r компонент равны u по определению H; оставшиеся обозначены g.'),
step('Все производные Dᵥg равны нулю.','Матрица производной имеет вид [[I,0],[Dᵤg,Dᵥg]]. Если какой-либо столбец блока Dᵥg ненулевой, ранг был бы больше r, что противоречит гипотезе.'),
step('Обозначим v₀=(aᵣ₊₁,…,aₙ). В малой прямоугольной окрестности H(a)=(u₀,v₀) имеем g(u,v)=g(u,v₀).','Для фиксированного u соединяем v с v₀ отрезком внутри выбранной прямоугольной окрестности. Производная g вдоль этого отрезка равна нулю; по основной теореме анализа значения на его концах совпадают.'),
step('Замена координат значений (u,w)↦(u,w−g(u,v₀)) даёт (u,0).','Эта замена имеет явную C¹-обратную (u,z)↦(u,z+g(u,v₀)).')], 'Постоянный ранг описывает всё отображение в окрестности.'),
proof('lagrange','smooth','Необходимое условие Лагранжа','В регулярной точке условного экстремума ∇f=Σλᵢ∇gᵢ.', ['f,g₁,…,gₘ класса C¹.','g(a)=0; строки Dg(a) независимы.','a — локальный экстремум f на M={g=0}.'],"Множители Лагранжа",[["smooth", "Регулярное множество уровня"], ["smooth", "Касательное пространство"], ["smooth", "Нормальное пространство"], ["four", "Матрица Якоби и правило цепочки"]],[
step('Теорема о неявной функции задаёт M около a регулярной параметризацией φ; её касательное пространство TₐM=ker Dg(a).','Невырожденный m×m-блок производной позволяет разрешить m координат через остальные. Дифференцирование g∘φ=0 даёт включение im Dφ⊆ker Dg; обе размерности равны n−m.',['y2-implicit']),
step('df(a)[v]=0 для каждого v∈TₐM.','Вектор v является скоростью кривой φ(u+tw). Ограничение f на эту кривую имеет экстремум при t=0, поэтому его производная равна нулю.'),
step('∇f(a)∈(ker Dg(a))⊥.','В евклидовых координатах df(a)[v]=∇f(a)·v; зануление для всех v означает ортогональность.'),
step('(ker Dg(a))⊥ совпадает с оболочкой строк Dg(a).','Каждая строка ортогональна ядру. Независимых строк m, а размерность ортогонального дополнения ядра также m; включение пространств равной размерности есть равенство.'),
step('Следовательно, ∇f(a)=Σλᵢ∇gᵢ(a).','Градиенты ограничений — строки Dg(a), поэтому принадлежность их оболочке и есть требуемое представление.')], 'Условие необходимо; само по себе оно не доказывает экстремум.'),
proof('restricted-hessian','smooth','Достаточное условие условного минимума','Положительная определённость D²ℒ(a) на TₐM в регулярной стационарной точке даёт строгий условный минимум.', ['f,g класса C²; rank Dg(a)=m.','ℒ=f−λ·g, Dℒ(a)=0.','D²ℒ(a)[v,v]>0 для всех ненулевых v∈TₐM.'],"Достаточное условие на касательном пространстве",[["smooth", "Касательное пространство"], ["smooth", "Множители Лагранжа"], ["four", "Локальные экстремумы"], ["higher", "Тейлор и алгебра приближений"]],[
step('Выбираем C²-параметризацию φ(u), φ(0)=a, ранга n−m.','Неявная функция имеет ту же C²-гладкость: из формулы её производной и C¹-гладкости блоков DF получаем C¹-производную, то есть C²-функцию.',['y2-implicit']),
step('На многообразии f∘φ=ℒ∘φ, поскольку g∘φ=0.','Лагранжиан отличается от f линейной комбинацией нулевых ограничений.'),
step('D²(f∘φ)(0)[w,w]=D²ℒ(a)[Dφ(0)w,Dφ(0)w].','Правило второй производной композиции содержит ещё Dℒ(a)[D²φ(0)[w,w]], но Dℒ(a)=0.'),
step('Эта квадратичная форма положительна при w≠0 и имеет оценку ≥c‖w‖² с c>0.','Dφ инъективна, её образ TₐM; минимум непрерывной положительной формы на единичной сфере положителен по компактности.'),
step('f(φ(w))−f(a)=½D²(f∘φ)(0)[w,w]+o(‖w‖²)>0 при достаточно малом w≠0.','Формула Тейлора и выбор остатка по модулю меньше c‖w‖²/4 сохраняют положительный знак.')], 'Получен строгий локальный минимум на M.'),
proof('null-countable','measure','Счётное объединение нулевых множеств','Счётное объединение измеримых множеств меры ноль имеет меру ноль.', ['Eₙ измеримы; μ(Eₙ)=0.'],"Нулевые множества и почти всюду",[["measure", "σ-алгебра и мера"], ["measure", "Внешняя мера и критерий Каратеодори"], ["measure", "Мера Лебега"]],[
step('Положим A₁=E₁ и Aₙ=Eₙ∖⋃ₖ<ₙEₖ для n≥2.','Разности и конечные объединения измеримых множеств измеримы.'),
step('Aₙ попарно не пересекаются и ⋃Aₙ=⋃Eₙ.','Каждая точка объединения относится к первому Eₙ, в котором появилась.'),
step('0≤μ(Aₙ)≤μ(Eₙ)=0, поэтому μ(Aₙ)=0.','Монотонность меры следует из аддитивности разложения Eₙ=Aₙ⊔(Eₙ∖Aₙ).'),
step('μ(⋃Eₙ)=μ(⋃Aₙ)=Σμ(Aₙ)=0.','Для попарно непересекающихся Aₙ применяется счётная аддитивность.')], 'Счётность объединения существенна: несчётное объединение точек может иметь положительную меру.'),
proof('measure-continuity','measure','Непрерывность меры снизу и сверху','Для Aₙ↑A имеем μ(Aₙ)↑μ(A); для Aₙ↓A это верно при μ(A₁)<∞.', ['Все множества измеримы.','Для убывающего случая первая мера конечна; достаточно конечности любого члена после отбрасывания начала.'],"Непрерывность меры по множествам",[["measure", "σ-алгебра и мера"]],[
step('В возрастающем случае разложим A на непересекающиеся D₁=A₁, Dₙ=Aₙ∖Aₙ₋₁.','Рост Aₙ гарантирует, что каждая точка появляется впервые в некотором Dₙ.'),
step('μ(A)=Σμ(Dₙ), а μ(A_N)=Σₙ≤Nμ(Dₙ).','Используем счётную и конечную аддитивность на непересекающихся частях.'),
step('μ(A_N)→μ(A), включая +∞.','Сумма неотрицательного ряда по определению есть предел его частичных сумм.'),
step('В убывающем случае Bₙ=A₁∖Aₙ возрастают к A₁∖A.','Дополнение относительно A₁ меняет направление включения.'),
step('μ(Aₙ)=μ(A₁)−μ(Bₙ)→μ(A₁)−μ(A₁∖A)=μ(A).','Конечность μ(A₁) разрешает вычитание и исключает выражение ∞−∞.')], 'Для непрерывности снизу конечность не нужна, для непрерывности сверху нужна.'),
proof('mct','lebesgue','Теорема Леви','Если 0≤fₙ↑f почти всюду, то ∫fₙ↑∫f, возможно до +∞.', ['fₙ измеримы и неотрицательны.','Монотонность и предел выполняются вне одного нулевого множества.'],"Теорема Леви",[["measure", "Непрерывность меры по множествам"], ["measure", "Простые функции и приближение"], ["lebesgue", "Неотрицательный интеграл"]],[
step('Изменим функции на общем нулевом множестве и считаем 0≤fₙ↑f всюду. Пусть L=lim∫fₙ≤∫f.','Нулевые изменения не влияют на интеграл; монотонность интеграла даёт возрастающий предел и верхнюю оценку.'),
step('Берём произвольную неотрицательную простую s≤f и число 0<t<1. Множества Eₙ={fₙ≥ts} возрастают и покрывают {s>0}.','Если s(x)>0, то fₙ(x)→f(x)≥s(x)>ts(x), поэтому точка с некоторого номера входит в Eₙ.'),
step('∫fₙ≥t∫s1_Eₙ и lim∫s1_Eₙ=∫s.','Первое следует из fₙ≥ts на Eₙ. Второе проверяется на конечном числе измеримых уровней s с помощью непрерывности меры снизу.',['y2-measure-continuity']),
step('L≥t∫s; переход t↑1 даёт L≥∫s.','Оценка справедлива для каждого t<1; при ∫s=∞ она уже заставляет L=∞.'),
step('Берём супремум по всем простым 0≤s≤f и получаем L≥∫f.','Так определяется интеграл неотрицательной измеримой функции. Вместе с первым шагом это даёт равенство.')], 'Монотонность позволяет перенести предел под интеграл без общей конечной мажоранты.'),
proof('fatou','lebesgue','Лемма Фату','Для измеримых fₙ≥0 выполнено ∫liminf fₙ≤liminf∫fₙ.', ['Все fₙ неотрицательны и измеримы.'],"Лемма Фату",[["lebesgue", "Неотрицательный интеграл"], ["lebesgue", "Теорема Леви"], ["sequences", "Верхний и нижний пределы"]],[
step('Положим gₙ=infₖ≥ₙfₖ. Тогда gₙ измеримы и неотрицательны.','Счётный инфимум измеримых функций измерим: {inf fₖ<a}=⋃{fₖ<a}.'),
step('gₙ↑liminf fₙ.','При удалении первых членов множество кандидатов для инфимума уменьшается; предел этих инфимумов — определение liminf.'),
step('∫gₙ≤infₖ≥ₙ∫fₖ.','Для каждого k≥n имеем gₙ≤fₖ, затем берём инфимум числовых верхних оценок.'),
step('По Леви ∫liminf fₙ=lim∫gₙ≤lim infₖ≥ₙ∫fₖ.','Слева применяется монотонная сходимость; справа предел хвостовых инфимумов равен liminf интегралов.',['y2-mct'])], 'Равенство в лемме не гарантировано.'),
proof('dct','lebesgue','Мажорируемая сходимость Лебега','Если fₙ→f почти всюду и |fₙ|≤g∈L¹, то ‖fₙ−f‖₁→0 и ∫fₙ→∫f.', ['Функции измеримы.','Одна неотрицательная интегрируемая g мажорирует все |fₙ| почти всюду.'],"Теорема Лебега о мажорируемой сходимости",[["measure", "Нулевые множества и почти всюду"], ["lebesgue", "Знак и пространство L¹"], ["lebesgue", "Лемма Фату"]],[
step('|f|≤g почти всюду, следовательно f∈L¹ и |fₙ−f|≤2g.','Переходим к пределу в |fₙ|≤g вне объединения нулевых исключений; затем используем треугольное неравенство.'),
step('hₙ=2g−|fₙ−f|≥0 и hₙ→2g почти всюду.','Неотрицательность следует из предыдущей оценки; сходимость разности следует из fₙ→f.'),
step('По Фату 2∫g≤liminf∫hₙ=2∫g−limsup∫|fₙ−f|.','Все интегралы g конечны, поэтому линейность и вычитание законны.',['y2-fatou']),
step('0≤limsup∫|fₙ−f|≤0, поэтому норма разности стремится к нулю.','Вычитаем конечное 2∫g из двух сторон и учитываем неотрицательность интегралов модулей.'),
step('|∫fₙ−∫f|≤∫|fₙ−f|→0.','Линейность интеграла и оценка модуля интеграла завершают переход к интегралам.')], 'Получена сходимость по норме L¹, более сильная, чем одно равенство пределов интегралов.'),
proof('normal-series','lebesgue','Нормально сходящийся ряд в L¹','Если Σ‖uₙ‖₁<∞, то Σuₙ сходится абсолютно почти всюду и в L¹.', ['uₙ измеримы и интегрируемы.','Сумма норм конечна.'],"Ряды и полнота L¹",[["lebesgue", "Знак и пространство L¹"], ["lebesgue", "Теорема Леви"]],[
step('Суммы G_N=Σₙ≤N|uₙ| возрастают к G=Σ|uₙ|.','Каждое добавляемое слагаемое неотрицательно.'),
step('∫G=lim∫G_N=Σ‖uₙ‖₁<∞.','Используем Леви и конечную линейность.',['y2-mct']),
step('G конечна почти всюду, поэтому ряд uₙ там сходится абсолютно.','Если μ{G=∞}>0, оценки ∫G≥M μ{G=∞} для всех M заставили бы интеграл быть бесконечным.'),
step('Определим сумму S вне нулевого исключения и положим S=0 на нём. Тогда |S|≤G и S∈L¹.','Поточечный предел измерим; интегрируемая мажоранта контролирует модуль.'),
step('‖S−Σₙ≤Nuₙ‖₁≤Σₙ> N‖uₙ‖₁→0.','Модуль остатка оценивается суммой модулей хвоста; Леви позволяет интегрировать эту неотрицательную сумму.')], 'Интеграл суммы равен сумме интегралов по непрерывности интеграла в L¹.'),
proof('l1-complete','lebesgue','Полнота L¹','Любая фундаментальная в L¹ последовательность имеет предел в L¹.', ['fₙ∈L¹.','Для каждого ε>0 при m,n≥N выполнено ‖fₙ−fₘ‖₁<ε.'],"Ряды и полнота L¹",[["lebesgue", "Знак и пространство L¹"], ["space", "Сходимость и фундаментальность в ℝⁿ"]],[
step('Выбираем подпоследовательность fₙₖ так, чтобы ‖fₙₖ₊₁−fₙₖ‖₁≤2⁻ᵏ.','Фундаментальность позволяет на каждом шаге выбрать достаточно поздние индексы.'),
step('Ряд fₙ₁+Σₖ≥1(fₙₖ₊₁−fₙₖ) сходится в L¹ к некоторой f.','Сумма норм приращений конечна; применяется доказанный результат о нормально сходящемся ряде.',['y2-normal-series']),
step('Его частичные суммы — члены fₙₖ, поэтому подпоследовательность сходится к f в L¹.','Промежуточные слагаемые телескопически сокращаются.'),
step('Для любого ε выбираем N фундаментальности с ошибкой ε/2 и k с nₖ≥N, ‖fₙₖ−f‖₁<ε/2.','Здесь используются обе имеющиеся сходимости: Коши для всей последовательности и норма для подпоследовательности.'),
step('При n≥N имеем ‖fₙ−f‖₁≤‖fₙ−fₙₖ‖₁+‖fₙₖ−f‖₁<ε.','Треугольное неравенство переносит предел подпоследовательности на всю фундаментальную последовательность.')], 'Пространство L¹ полно.'),
proof('tonelli-rectangles','multiple','Теорема Тонелли для меры Лебега','Для неотрицательной измеримой функции на ℝⁿ×ℝᵐ оба повторных интеграла равны интегралу по мере произведения.', ['Доказательство начинается на прямоугольнике A×B конечной меры Лебега и затем переходит ко всему пространству.','f измерима относительно произведения борелевских σ-алгебр; нулевые изменения допускаются почти всюду.'],"Теорема Тонелли",[["multiple", "Произведение мер"], ["multiple", "Сечения, π-системы и λ-системы"], ["measure", "Простые функции и приближение"], ["lebesgue", "Теорема Леви"]],[
step('Для индикатора измеримого прямоугольника E×F равенство верно: ∫1_E(x)1_F(y)dy=1_E(x)λ(F), затем интеграл по x равен λ(E)λ(F).','Так определяется мера произведения на прямоугольниках.'),
step('Обозначим через 𝒟 семейство множеств C, измеримых относительно произведения σ-алгебр на A×B, для которых сечения измеримы, функция x↦λ(Cₓ) измерима и ∫λ(Cₓ)dx=(λ×λ)(C). Это λ-система.','Всё пространство принадлежит 𝒟. Для дополнения относительно A×B используем λ(B∖Cₓ)=λ(B)−λ(Cₓ), где все меры конечны; для счётного дизъюнктного объединения используем аддитивность и Леви.',['y2-mct']),
step('λ-система, содержащая π-систему прямоугольников, содержит порождённую ими σ-алгебру.','Обоснование π–λ-принципа: для минимальной λ-системы 𝓛 и фиксированного прямоугольника P семейство {E:P∩E∈𝓛} — λ-система. Для дополнений используем P∩Eᶜ=P∖(P∩E). Разность вложенных элементов λ-системы снова принадлежит ей, поскольку это дополнение дизъюнктного объединения. Семейство содержит все прямоугольники, значит содержит 𝓛. Повторяем с фиксированным E∈𝓛 и получаем замкнутость 𝓛 по пересечениям. λ-система с конечными пересечениями — σ-алгебра: из дополнений и пересечений получаем конечные объединения, а счётное объединение раскладываем на дизъюнктные части.'),
step('Равенство доказано для индикаторов всех множеств произведения σ-алгебр, затем для неотрицательных простых функций.','После индикаторов применяем конечную линейность к измеримому разбиению.'),
step('Выбираем простые sₙ↑f и трижды применяем Леви: к интегралу по y, затем по x и к интегралу на произведении.','Так измеримость и равенство переносятся с простых функций на произвольную неотрицательную f. Перестановка ролей x,y даёт второй порядок.',['y2-mct']),
step('Для ℝⁿ×ℝᵐ применяем результат к возрастающим конечным прямоугольникам и снова Леви.','Исчерпание [-N,N]ⁿ×[-N,N]ᵐ покрывает всё пространство. Для завершения меры берём представителя, измеримого относительно произведения; индикатор нулевого исключения по уже доказанному результату имеет нулевые сечения почти всюду.')], 'Тонелли допускает +∞, поскольку все функции неотрицательны.', 'Доказан случай мер Лебега на евклидовых пространствах. Общий σ-конечный случай следует тем же π–λ-аргументом и исчерпанием конечными прямоугольниками.'),
proof('fubini','multiple','Теорема Фубини','Если f∈L¹ на произведении евклидовых пространств, оба повторных интеграла равны ∫f.', ['f измерима.','∫|f(x,y)|dxdy<∞.'],"Теорема Фубини",[["multiple", "Теорема Тонелли"], ["lebesgue", "Знак и пространство L¹"]],[
step('По Тонелли ∫(∫|f(x,y)|dy)dx=∫|f|<∞.','Неотрицательная функция |f| удовлетворяет условиям Тонелли.',['y2-tonelli-rectangles']),
step('Внутренний интеграл модуля конечен почти для всех x.','Неотрицательная измеримая функция с конечным интегралом конечна почти всюду.'),
step('Для этих x сечение f(x,·) интегрируемо и ∫f(x,y)dy=∫f⁺(x,y)dy−∫f⁻(x,y)dy.','Оба неотрицательных интеграла конечны, поскольку f⁺,f⁻≤|f|.'),
step('Интегрируем разность по x и применяем Тонелли к f⁺ и f⁻. Получаем ∫∫f=∫f⁺−∫f⁻=∫f.','Из ∫f±≤∫|f|<∞ вычитание законно. Для другого порядка меняем x,y местами.')], 'Интегрируемость модуля оправдывает все вычитания и перестановки.'),
proof('change-triangular','multiple','Замена переменных для треугольного отображения','Если Φ(u,v)=(u,φ(u,v)) — C¹-диффеоморфизм, то ∫f(x,y)dxdy=∫f(u,φ(u,v))|∂ᵥφ|dudv.', ['Области открыты в ℝ².','Φ взаимно однозначно отображает одну открытую область на другую. Производная ∂ᵥφ нигде не обращается в ноль.','f≥0 измерима или f интегрируема.'],"Якобиан замены",[["multiple", "Одномерная замена в интеграле Лебега"], ["multiple", "Теорема Тонелли"], ["higher", "Теорема об обратном отображении"], ["four", "Матрица Якоби и правило цепочки"]],[
step('Зафиксируем u. Его вертикальное сечение открытой области есть не более чем счётное объединение непересекающихся интервалов.','Каждый интервал содержит рациональную точку, поэтому компонент не более чем счётно.'),
step('На каждой компоненте применима одномерная замена y=φ(u,v): dy=|∂ᵥφ(u,v)|dv для положительной меры.','Производная непрерывна и не равна нулю, значит знак на интервале постоянен и замена монотонна. Применяем одномерную формулу для интеграла Лебега, полученную из формулы для индикаторов интервалов.'),
step('Складываем интегралы по компонентам. Их образы не пересекаются.','Непересечение следует из глобальной инъективности Φ; для неотрицательных функций счётное сложение интегралов разрешено Леви.',['y2-mct']),
step('Интегрируем полученное равенство по u и применяем Тонелли.','Неотрицательность разрешает оба повторных интеграла; для L¹-функции рассуждение применяется отдельно к f⁺ и f⁻.',['y2-tonelli-rectangles']),
step('Матрица DΦ=[[1,0],[∂ᵤφ,∂ᵥφ]] имеет определитель ∂ᵥφ.','Формула совпадает с общим видом веса |det DΦ| в этом конкретном классе замен.')], 'Замена переменных доказана для указанного треугольного класса.', 'Это полный разбор частного случая, а не доказательство общей многомерной формулы замены.'),
proof('gamma','parameters','Рекуррентная формула гамма-функции','Для s>0 выполняется Γ(s+1)=sΓ(s), откуда Γ(n+1)=n!.', ['Γ(s)=∫₀∞tˢ⁻¹e⁻ᵗdt.','s>0.'],"Гамма-функция",[["improper", "Сравнение и степенные эталоны"], ["three", "Интегрирование по частям"]],[
step('Интеграл Γ(s) сходится: у нуля tˢ⁻¹ интегрируема, а на бесконечности экспонента подавляет любую фиксированную степень.','У нуля степень s−1>−1; для большого t имеем tᵏe⁻ᵗ≤C e⁻ᵗ/², поскольку tᵏe⁻ᵗ/² ограничена.'),
step('На [ε,R] интегрируем tˢe⁻ᵗ по частям: ∫ε^R tˢe⁻ᵗdt=[−tˢe⁻ᵗ]ε^R+s∫ε^R tˢ⁻¹e⁻ᵗdt.','Берём u=tˢ и dv=e⁻ᵗdt; на конечном положительном отрезке обе функции C¹.'),
step('Граничные слагаемые стремятся к нулю при ε↓0 и R↑∞.','При s>0 имеем εˢe⁻ε→0, а Rˢe⁻ᴿ→0 по экспоненциальной оценке первого шага.'),
step('Переходим к пределам и получаем Γ(s+1)=sΓ(s).','Оба несобственных интеграла сходятся, поэтому предел конечного равенства законен.'),
step('Γ(1)=∫₀∞e⁻ᵗdt=1; повторение рекурсии даёт Γ(n+1)=n!.','Последовательно подставляем s=n,n−1,…,1.')], 'Гамма-функция продолжает факториал на положительные вещественные аргументы.'),
proof('beta','parameters','Соотношение бета- и гамма-функций','При p,q>0 выполняется Γ(p)Γ(q)=Γ(p+q)B(p,q).', ['B(p,q)=∫₀¹tᵖ⁻¹(1−t)ᑫ⁻¹dt.','p,q>0.'],"Бета-функция",[["parameters", "Гамма-функция"], ["multiple", "Теорема Тонелли"], ["multiple", "Якобиан замены"]],[
step('Произведение гамма-интегралов равно ∫₀∞∫₀∞uᵖ⁻¹vᑫ⁻¹e⁻ᵘ⁻ᵛdudv.','Подынтегральная функция неотрицательна, поэтому Тонелли разрешает повторный интеграл и разделение переменных.',['y2-tonelli-rectangles']),
step('Сначала заменяем v=r−u при фиксированном u; область становится 0<u<r<∞.','Это одномерная линейная замена с модулем производной 1. Тонелли позволяет затем интегрировать сначала по u при фиксированном r.'),
step('При фиксированном r>0 заменяем u=rt, 0<t<1, du=r dt.','Одномерная замена на (0,r) превращает uᵖ⁻¹(r−u)ᑫ⁻¹ в rᵖ⁺ᑫ⁻²tᵖ⁻¹(1−t)ᑫ⁻¹.'),
step('Интеграл равен ∫₀∞rᵖ⁺ᑫ⁻¹e⁻ʳdr · ∫₀¹tᵖ⁻¹(1−t)ᑫ⁻¹dt.','Множитель r от du даёт степень p+q−1; неотрицательность снова разрешает разделение.'),
step('Первый множитель Γ(p+q)>0, второй B(p,q), поэтому B(p,q)=Γ(p)Γ(q)/Γ(p+q).','Положительность и конечность Γ(p+q) разрешают деление.')], 'Условия p,q>0 обеспечивают сходимость у обоих концов бета-интеграла.'),
proof('gaussian','parameters','Гауссов интеграл','∫ℝe⁻ˣ²dx=√π.', ['Интеграл берётся по всей вещественной прямой.'],"Гауссов интеграл",[["parameters", "Гамма-функция"], ["multiple", "Теорема Тонелли"], ["multiple", "Полярные и сферические координаты"]],[
step('Обозначим I=∫ℝe⁻ˣ²dx. Он положителен и конечен.','На |x|≥1 имеем e⁻ˣ²≤e⁻|x|, а на [−1,1] функция ограничена.'),
step('I²=∫ℝ²e⁻⁽ˣ²⁺ʸ²⁾dxdy.','Тонелли применима к неотрицательному произведению двух одномерных функций.',['y2-tonelli-rectangles']),
step('Для диска радиуса R интеграл равен 2π∫₀ᴿe⁻ʳ²rdr=π(1−e⁻ᴿ²).','В полярных координатах якобиан r; исключённые луч и начало имеют меру ноль. Это применение формулы полярной замены из теории.'),
step('При R↑∞ диски исчерпывают ℝ², поэтому I²=π.','Интегралы неотрицательной функции по возрастающим областям сходятся к полному интегралу по Леви.',['y2-mct']),
step('I=√π, поскольку I>0.','Из двух алгебраических корней выбираем положительный, так как подынтегральная функция положительна.')], 'После замены t=x² следует Γ(1/2)=√π.', 'Доказательство использует формулу полярной замены, сформулированную в главе «Произведения мер и замена переменных».')
];
SECOND_YEAR_PROOFS.push(
proof('uniform-majorant','uniformintegrals','Мажорантный признак равномерной сходимости','Если |f(x,a)|≤g(x) и ∫ᵦ∞g<∞, интегралы f сходятся абсолютно и равномерно по a.', ['g≥0 интегрируема на [b,∞).','Для каждого параметра конечные интегралы f существуют.','Одна оценка действует для всех параметров.'],"Мажоранта",[["uniformintegrals", "Определение равномерного хвоста"], ["uniformintegrals", "Критерий Коши"], ["improper", "Абсолютная сходимость"]],[
step('Для каждого фиксированного a интеграл ∫|f(x,a)|dx конечен.','По сравнению он не превосходит ∫g.'),
step('Для любого R≥b остаток удовлетворяет |∫ᴿ∞f(x,a)dx|≤∫ᴿ∞g(x)dx.','Модуль интеграла не больше интеграла модуля; затем используем общую мажоранту.'),
step('Правая часть стремится к нулю при R→∞.','Это остаток сходящегося неотрицательного несобственного интеграла.'),
step('Берём супремум по a и получаем supₐ|∫ᴿ∞f|≤∫ᴿ∞g→0.','Правая часть не зависит от параметра. Это определение равномерной сходимости хвостов.')], 'Одна интегрируемая мажоранта контролирует всё семейство.'),
proof('uniform-dirichlet','uniformintegrals','Равномерный признак Дирихле','Если первообразные f ограничены одной константой, а монотонный множитель g стремится к нулю равномерно, ∫fg сходится равномерно.', ['f(·,a) непрерывна на каждом конечном отрезке.','F(X,a)=∫ᵦˣf(t,a)dt и |F(X,a)|≤C для всех X,a.','g(·,a) класса C¹ и монотонна.','supₐ|g(R,a)|→0.'],"Равномерный признак Дирихле",[["uniformintegrals", "Определение равномерного хвоста"], ["uniformintegrals", "Критерий Коши"], ["improper", "Признаки Дирихле и Абеля"], ["three", "Интегрирование по частям"]],[
step('Для S>R положим H(x,a)=F(x,a)−F(R,a), x∈[R,S]; тогда H(R,a)=0 и |H|≤2C.','Вычитаем два значения первообразной, каждое по модулю не больше C.'),
step('∫ᴿˢfg=H(S,a)g(S,a)−∫ᴿˢH(x,a)∂ₓg(x,a)dx.','Это интегрирование по частям на конечном отрезке; H′=f.'),
step('|∫ᴿˢfg|≤2C(|g(S,a)|+|g(R,a)−g(S,a)|)=2C|g(R,a)|.','Монотонная функция, стремящаяся к нулю, сохраняет знак и имеет вариацию |g(R)|−|g(S)|.'),
step('supₐ|∫ᴿˢfg|≤2C supₐ|g(R,a)|→0 независимо от S>R.','Это равномерный критерий Коши для несобственного интеграла.')], 'Абсолютной сходимости признак не утверждает.'),
proof('uniform-abel','uniformintegrals','Равномерный признак Абеля','Если ∫f сходится равномерно, а g монотонна и равномерно ограничена, ∫fg сходится равномерно.', ['f(·,a) непрерывна на каждом конечном отрезке.','g(·,a) класса C¹ и монотонна.','|g(x,a)|≤M для всех x,a.','Интегралы ∫ᵦ∞f(x,a)dx сходятся равномерно.'],"Равномерный признак Абеля",[["uniformintegrals", "Критерий Коши"], ["uniformintegrals", "Равномерный признак Дирихле"], ["three", "Интегрирование по частям"]],[
step('Для любого η>0 существует R₀: при x≥R≥R₀ для всех a имеем |H(x,a)|=|∫ᴿˣf(t,a)dt|<η.','Это равномерный критерий Коши для исходных интегралов.'),
step('По частям ∫ᴿˢfg=H(S,a)g(S,a)−∫ᴿˢH∂ₓg.','H(R,a)=0, поэтому начальное граничное слагаемое отсутствует.'),
step('|∫ᴿˢfg|≤η(M+|g(S,a)−g(R,a)|)≤3Mη.','Монотонность превращает интеграл |g′| в разность концов, по модулю не превосходящую 2M.'),
step('Выбирая η<ε/(3M) при M>0, получаем равномерный критерий Коши для fg.','Если M=0, множитель g тождественно нулевой и утверждение непосредственно верно.')], 'Для Абеля не требуется, чтобы g стремилась к нулю.'),
proof('l1-boxes','lebesgue','Приближение L¹-функции прямоугольными ступенями','Конечные линейные комбинации индикаторов ограниченных прямоугольников плотны в L¹(ℝⁿ).', ['Используется мера Лебега.','f∈L¹(ℝⁿ).'],"Приближение ступенями на прямоугольниках",[["measure", "Мера Лебега"], ["measure", "Непрерывность меры по множествам"], ["measure", "Простые функции и приближение"], ["lebesgue", "Знак и пространство L¹"], ["lebesgue", "Теорема Лебега о мажорируемой сходимости"], ["space", "Компактность и открытые покрытия"]],[
step('Для множества E конечной меры и δ>0 найдётся открытое O⊇E с λ(O∖E)<δ.','По определению внешней меры покрываем E счётными прямоугольниками с суммой объёмов <λ(E)+δ/2 и слегка расширяем каждый до открытого с общей добавкой <δ/2.'),
step('Существует компактное K⊆E с λ(E∖K)<δ.','Сначала пересекаем E с большим замкнутым кубом Q, оставляя хвост меры <δ/2 по непрерывности снизу. Применяем первый шаг к Q∖E и берём K=Q∖U, где U — открытое покрытие этого дополнения с излишком меры <δ/2.',['y2-measure-continuity']),
step('Компакт K покрывается конечным числом открытых прямоугольников с объединением P⊂O. Тогда λ(E△P)≤λ(O∖K)<2δ.','Для каждой точки K выбираем малый прямоугольник внутри O; компактность даёт конечное подпокрытие. Перекрытия конечного семейства можно разбить на конечное прямоугольное разбиение, не меняя индикатор почти всюду.'),
step('Функцию f можно приблизить в L¹ ограниченной функцией на ограниченном кубе.','Отсекаем область и значения: f_N=f1_{‖x‖∞≤N, |f|≤N}. Тогда |f−f_N|→0 почти всюду и |f−f_N|≤|f|, поэтому действует мажорируемая сходимость.',['y2-dct']),
step('Округление значений f_N до шага 1/k даёт простую функцию s с ошибкой по норме ≤λ(Q)/k.','В каждом значении ошибка не больше 1/k, а носитель лежит в кубе конечной меры; число уровней конечно.'),
step('Каждый индикатор уровня s заменяем индикатором конечного объединения прямоугольников с достаточно малой симметрической разностью.','Имеем ‖Σcⱼ1_Eⱼ−Σcⱼ1_Pⱼ‖₁≤Σ|cⱼ|λ(Eⱼ△Pⱼ). Членов конечное число, поэтому их суммарную ошибку можно сделать меньше любого ε.')], 'Прямоугольные ступени позволяют переносить явные геометрические оценки на L¹-функции.'),
proof('convolution','approximation','Свёртка в L¹: норма и масса','Для f,g∈L¹ свёртка определена почти всюду, принадлежит L¹, ‖f*g‖₁≤‖f‖₁‖g‖₁ и ∫f*g=(∫f)(∫g).', ['f,g∈L¹(ℝⁿ).','(f*g)(x)=∫f(x−y)g(y)dy.'],"Свёртка",[["lebesgue", "Знак и пространство L¹"], ["multiple", "Теорема Тонелли"], ["multiple", "Теорема Фубини"], ["measure", "Мера Лебега"]],[
step('∫∫|f(x−y)g(y)|dydx=∫|g(y)|(∫|f(x−y)|dx)dy.','Тонелли разрешает изменение порядка для неотрицательной функции.',['y2-tonelli-rectangles']),
step('Внутренний интеграл равен ‖f‖₁, поэтому двойной интеграл равен ‖f‖₁‖g‖₁<∞.','Перенос x↦x−y сохраняет меру Лебега.'),
step('Для почти всех x интеграл по y абсолютно сходится, и ∫|f*g|≤‖f‖₁‖g‖₁.','Конечность двойного интеграла означает конечность внутреннего почти всюду; модуль интеграла не превосходит интеграла модуля.'),
step('По Фубини ∫(f*g)(x)dx=∫g(y)(∫f(x−y)dx)dy=(∫f)(∫g).','Абсолютная интегрируемость уже доказана, поэтому перестановка для знакопеременного произведения законна.',['y2-fubini'])], 'Свёртка двух L¹-функций сохраняет произведение их интегралов.'),
proof('translation','approximation','Непрерывность сдвига в L¹','Для f∈L¹(ℝⁿ) выполнено ‖f(·−h)−f‖₁→0 при h→0.', ['f∈L¹(ℝⁿ).','Сдвиг действует на всё евклидово пространство.'],"Непрерывность сдвига и сглаживание",[["lebesgue", "Знак и пространство L¹"], ["lebesgue", "Приближение ступенями на прямоугольниках"], ["measure", "Мера Лебега"]],[
step('Для индикатора ограниченного прямоугольника Q ошибка равна λ((Q+h)△Q)→0.','Пересечение Q и Q+h — прямоугольник с длинами сторон max(ℓᵢ−|hᵢ|,0), поэтому его объём стремится к λ(Q); симметрическая разность имеет меру 2λ(Q)−2λ(Q∩(Q+h)).'),
step('То же верно для конечной линейной комбинации p таких индикаторов.','По треугольному неравенству ошибка комбинации не больше конечной суммы |cᵢ| умножить на ошибки индикаторов.'),
step('Для ε>0 выбираем p с ‖f−p‖₁<ε/3.','Плотность прямоугольных ступеней доказана отдельно.',['y2-l1-boxes']),
step('‖f(·−h)−f‖₁≤2‖f−p‖₁+‖p(·−h)−p‖₁<ε при достаточно малом h.','Сдвиг сохраняет L¹-норму. Две ошибки приближения меньше ε/3 каждая, а третье слагаемое контролируется вторым шагом.')], 'Сдвиг непрерывен по норме, даже если сама функция имеет скачки.'),
proof('approximate-identity','approximation','Приближающая единица в L¹','Если ρ≥0, ∫ρ=1 и ρ_ε(y)=ε⁻ⁿρ(y/ε), то ‖f*ρ_ε−f‖₁→0 для f∈L¹.', ['ρ∈L¹(ℝⁿ), ρ≥0, ∫ρ=1.','f∈L¹(ℝⁿ); ε↓0.'],"Приближающая единица",[["approximation", "Свёртка"], ["approximation", "Непрерывность сдвига и сглаживание"], ["multiple", "Теорема Тонелли"]],[
step('∫ρ_ε=1 и ∫_{|y|≥δ}ρ_ε(y)dy=∫_{|z|≥δ/ε}ρ(z)dz→0 для каждого δ>0.','Замена y=εz компенсирует ε⁻ⁿ, а хвост интегрируемой ρ стремится к нулю.'),
step('f*ρ_ε−f=∫ρ_ε(y)[f(·−y)−f]dy и ‖f*ρ_ε−f‖₁≤∫ρ_ε(y)‖f(·−y)−f‖₁dy.','Первое равенство использует единичную массу; второе — треугольное неравенство и Тонелли для модуля.',['y2-tonelli-rectangles']),
step('Для любого η>0 выбираем δ так, что |y|<δ ⇒ ‖f(·−y)−f‖₁<η.','Это непрерывность сдвига в L¹.',['y2-translation']),
step('Ошибка не больше η+2‖f‖₁∫_{|y|≥δ}ρ_ε(y)dy.','На ближней части используем оценку η и массу ≤1; на дальней — ‖f(·−y)−f‖₁≤2‖f‖₁.'),
step('Сначала ε↓0, затем η↓0, и норма ошибки стремится к нулю.','При фиксированном δ хвост ядра исчезает; верхний предел ошибки не больше произвольного η.')], 'Нормированное ядро с концентрацией массы в нуле приближает любую L¹-функцию.'),
proof('weierstrass','approximation','Приближение многочленами Бернштейна','Для непрерывной f на [0,1] многочлены Bₙf сходятся к f равномерно.', ['f∈C[0,1].','Bₙf(x)=Σₖ₌₀ⁿf(k/n)C(n,k)xᵏ(1−x)ⁿ⁻ᵏ.'],"Теорема Вейерштрасса",[["derivatives", "Высшие производные и формула Лейбница"], ["limits", "Равномерная непрерывность и Кантор"], ["five", "Поточечная и равномерная сходимость"]],[
step('Положим wₙₖ(x)=C(n,k)xᵏ(1−x)ⁿ⁻ᵏ. Тогда wₙₖ≥0 и Σwₙₖ=1.','Это биномиальная формула (x+(1−x))ⁿ=1.'),
step('Σwₙₖ(k/n−x)²=x(1−x)/n≤1/(4n).','Из дифференцирования биномиальной формулы получаем Σkwₙₖ=nx и Σk(k−1)wₙₖ=n(n−1)x²; подстановка в квадрат даёт дисперсию.'),
step('Сумма весов с |k/n−x|≥δ не больше 1/(4nδ²).','На этих индексах (k/n−x)²≥δ², поэтому δ²Σдал wₙₖ не превосходит суммы квадратных отклонений.'),
step('Пусть M=max|f|. Для произвольного η>0 выбираем δ>0: |u−v|<δ ⇒ |f(u)−f(v)|<η.','Непрерывная функция на компактном отрезке ограниченна и равномерно непрерывна.'),
step('|Bₙf(x)−f(x)|≤η+2M/(4nδ²) одновременно для всех x.','Разбиваем сумму на близкие индексы, где разность меньше η, и далёкие, где разность не больше 2M и мала сумма весов.'),
step('При фиксированном δ выбираем n достаточно большим, затем делаем η произвольно малым.','Полученная оценка не зависит от x, поэтому это равномерная, а не только поточечная сходимость.')], 'Непрерывная функция допускает равномерное приближение полиномами; аналитичность не требуется.'),
proof('hausdorff-lipschitz','surface','Липшицева оценка меры Хаусдорфа','Для L-липшицева F выполнено Hᵏ(F(E))≤LᵏHᵏ(E).', ['k≥1; Hᵏ имеет одинаковую нормировку в исходном и конечном пространствах.','d(Fx,Fy)≤L d(x,y).'],"Измеримость и геометрические оценки",[["surface", "Мера Хаусдорфа"], ["continuity", "Линейные отображения и их норма"], ["space", "Шары и окрестности"]],[
step('Пусть E⊆⋃Uᵢ и diam Uᵢ≤δ. Тогда F(E)⊆⋃F(Uᵢ).','Образ объединения покрывает образ каждого его подмножества.'),
step('diam F(Uᵢ)≤L diam Uᵢ.','Берём супремум липшицевой оценки расстояний по всем парам точек Uᵢ.'),
step('Сумма k-х степеней диаметров нового покрытия не больше LᵏΣ(diam Uᵢ)ᵏ.','Возводим неотрицательные неравенства в степень k и складываем.'),
step('При L>0 берём инфимум по исходным δ-покрытиям, затем δ↓0: Hᵏ(F(E))≤LᵏHᵏ(E).','Новое покрытие имеет диаметры ≤Lδ, а Lδ тоже стремится к нулю.'),
step('При L=0 образ непустого E состоит из одной точки и имеет Hᵏ-меру 0.','Все расстояния в образе нулевые; точку можно покрыть множеством сколь угодно малого диаметра.')], 'Оценка получена непосредственно из определения меры через покрытия.'),
proof('gram','surface','Площадь линейной параметризации и определитель Грама','Для инъективного линейного A:ℝᵏ→ℝⁿ множитель k-мерного объёма равен √det(AᵀA).', ['rank A=k.','Объём в плоскости im A измеряется евклидовой k-мерной мерой.'],"Якобиан площади",[["space", "Линейное пространство и базис"], ["space", "Норма и скалярное произведение"], ["surface", "Мера Хаусдорфа"], ["multiple", "Якобиан замены"]],[
step('Выбираем ортонормированный базис плоскости im A и записываем A=QB, где QᵀQ=I, а B — обратимая k×k-матрица.','Столбцы Q — этот базис; B содержит координаты столбцов A.'),
step('Отображение Q сохраняет расстояния и k-мерный объём в этой плоскости.','‖Qv‖²=vᵀQᵀQv=‖v‖²; евклидов объём определяется относительно ортонормированных координат.'),
step('Параллелепипед с рёбрами столбцов B имеет объём |det B|.','Это определяющее геометрическое свойство определителя квадратной линейной замены.'),
step('AᵀA=BᵀQᵀQB=BᵀB, поэтому det(AᵀA)=(det B)².','Используем QᵀQ=I, мультипликативность определителя и det Bᵀ=det B.'),
step('√det(AᵀA)=|det B| — искомый неотрицательный множитель.','Объём положителен и не зависит от ориентации выбранного базиса.')], 'Это обоснование линейного якобиана площади.', 'Отождествление интеграла этого локального якобиана с Hᵏ-мерой нелинейного образа — отдельная общая теорема площади; она здесь не подменяется линейным вычислением.'),
proof('coarea-projection','surface','Формула кообъёма для координатной проекции','Для F(x,z)=x, x∈ℝᵐ,z∈ℝⁿ⁻ᵐ, интеграл g по пространству равен интегралу её интегралов по слоям.', ['g≥0 измерима или g∈L¹(ℝⁿ).','F — координатная проекция, n≥m.'],"Формула кообъёма",[["surface", "Мера Хаусдорфа"], ["surface", "Якобиан площади"], ["multiple", "Теорема Тонелли"], ["multiple", "Теорема Фубини"]],[
step('DF=[Iₘ,0], поэтому DF DFᵀ=Iₘ и JₘF=1.','Производная координатной проекции постоянна; определитель единичной матрицы равен 1.'),
step('Слой F⁻¹(x) есть плоскость {x}×ℝⁿ⁻ᵐ.','Уравнение F(x,z)=x фиксирует первые m координат и оставляет остальные свободными.'),
step('Его Hⁿ⁻ᵐ-мера соответствует мере Лебега dz в ортонормированных координатах z.','Нормированная мера Хаусдорфа на евклидовой плоскости совпадает с обычным объёмом той же размерности.'),
step('∫g JₘF dxdz=∫ℝᵐ(∫ℝⁿ⁻ᵐg(x,z)dz)dx.','Левая сторона имеет JₘF=1; равенство — Тонелли для g≥0 или Фубини для L¹-функции.',['y2-tonelli-rectangles','y2-fubini'])], 'Формула доказана для координатной проекции.', 'Для произвольной C¹-субмерсии дополнительно нужны локальное выпрямление и общая формула площади слоёв.')
);
SECOND_YEAR_PROOFS.push(
proof('d-squared','forms','Внешняя производная удовлетворяет d²=0','Для дифференциальной формы с C²-коэффициентами d(dω)=0.', ['ω=Σ_I a_I dx_I.','Все a_I имеют непрерывные вторые производные.'],"Внешняя производная",[["forms", "Кососимметричные формы"], ["four", "Второй дифференциал и формула Тейлора"]],[
step('dω=Σⱼ,I(∂ⱼa_I)dxⱼ∧dx_I.','Это координатное определение внешней производной; формы dx_I имеют постоянные коэффициенты.'),
step('d²ω=Σₗ,ⱼ,I(∂ₗ∂ⱼa_I)dxₗ∧dxⱼ∧dx_I.','Применяем то же определение к коэффициентам первой внешней производной.'),
step('Слагаемые с l=j равны нулю.','Внешнее произведение одинаковых 1-форм dxⱼ∧dxⱼ=0 по кососимметрии.'),
step('Слагаемые с l≠j попарно сокращаются.','Непрерывность вторых производных даёт ∂ₗ∂ⱼa_I=∂ⱼ∂ₗa_I, а перестановка dxₗ,dxⱼ меняет знак внешнего произведения.')], 'Точность ω=dη влечёт замкнутость dω=0 при достаточной гладкости η.'),
proof('pullback','forms','Перенос формы согласуется с внешней производной','Для C²-отображения Φ и C¹-формы ω выполняется d(Φ*ω)=Φ*(dω).', ['Отображение и форма определены на соответствующих открытых областях.','Гладкости достаточно для правила цепочки и d²Φᵢ=0.'],"Обратный образ формы",[["forms", "Кососимметричные формы"], ["forms", "Внешняя производная"], ["four", "Матрица Якоби и правило цепочки"]],[
step('Для функции a имеем Φ*a=a∘Φ и d(a∘Φ)=Σⱼ(∂ⱼa∘Φ)dΦⱼ.','Это обычное правило цепочки для скалярной композиции.'),
step('Для координатной 1-формы Φ*(dyⱼ)=dΦⱼ, поэтому d(Φ*dyⱼ)=d²Φⱼ=0.','Перенос подставляет DΦ в аргумент 1-формы; d² функции равно нулю.',['y2-d-squared']),
step('Для одного слагаемого ω=a dyᵢ₁∧…∧dyᵢₖ его перенос равен (a∘Φ)dΦᵢ₁∧…∧dΦᵢₖ.','Обратный образ сохраняет внешнее произведение: обе стороны вычисляются подстановкой DΦ в кососимметричную многолинейную форму.'),
step('При внешнем дифференцировании остаётся только d(a∘Φ)∧dΦᵢ₁∧…∧dΦᵢₖ.','В правиле Лейбница все производные d(dΦᵢ) равны нулю по второму шагу.'),
step('Подстановка первого шага даёт ровно перенос da∧dyᵢ₁∧…∧dyᵢₖ; затем складываем по I.','Линейность d и переноса переносит равенство с одного слагаемого на произвольную форму.')], 'Правило цепочки для форм позволяет переносить формулу Стокса между координатами.'),
proof('poincare-one','forms','Лемма Пуанкаре для 1-форм на звёздной области','Замкнутая C¹-1-форма на звёздной открытой области имеет потенциал.', ['Область звёздна относительно 0; другой центр сводится к этому переносом.','ω=Σaᵢ(x)dxᵢ, aᵢ∈C¹.','Замкнутость означает ∂ⱼaᵢ=∂ᵢaⱼ.'],"Замкнутость и точность",[["forms", "Замкнутые формы и звёздные области"], ["forms", "Внешняя производная"], ["parameters", "Дифференцирование под интегралом"]],[
step('Определим f(x)=∫₀¹Σᵢxᵢaᵢ(tx)dt.','Отрезок [0,x] лежит в области по звёздности; интеграл есть интеграл ω вдоль этого отрезка.'),
step('∂ⱼf(x)=∫₀¹[aⱼ(tx)+tΣᵢxᵢ∂ⱼaᵢ(tx)]dt.','Дифференцируем конечный интеграл: на компактном отрезке и в малой окрестности x коэффициенты и их производные непрерывны, поэтому правило Лейбница применимо.'),
step('По замкнутости ∂ⱼaᵢ=∂ᵢaⱼ, и подынтегральное выражение равно d/dt[t aⱼ(tx)].','Дифференцируем произведение t aⱼ(tx) по t и используем правило цепочки.'),
step('∂ⱼf(x)=[t aⱼ(tx)]₀¹=aⱼ(x).','Формула Ньютона — Лейбница даёт значение при t=1; при t=0 множитель t зануляет конечное aⱼ(0).'),
step('df=Σ∂ⱼf dxⱼ=ω.','Все коэффициенты дифференциала совпали с коэффициентами исходной формы.')], 'Найден явный потенциал.', 'Здесь доказана версия для 1-форм. Для форм большей степени используется оператор гомотопии; общая версия не следует лишь из формулы потенциала функции.'),
proof('stokes-local','forms','Формула Стокса в координатном полупространстве','Для компактно поддержанной C¹-(k−1)-формы на H={xₖ≥0} выполнено ∫∂Hω=∫H dω.', ['H имеет стандартную ориентацию dx₁∧…∧dxₖ.','ω=Σᵢ(−1)ⁱ⁻¹aᵢ dx₁∧…∧d̂xᵢ∧…∧dxₖ.','Коэффициенты C¹ с компактным носителем, гладкие до края.'],"Формула Стокса в полупространстве",[["forms", "Внешняя производная"], ["forms", "Ориентация и край"], ["forms", "Цепи и интегрирование"], ["multiple", "Теорема Фубини"], ["three", "Основная теорема и формула Ньютона — Лейбница"]],[
step('dω=(Σᵢ∂ᵢaᵢ)dx₁∧…∧dxₖ.','При дифференцировании выживает только производная по пропущенной координате i. Перестановка dxᵢ на его место компенсирует знак (−1)ⁱ⁻¹.'),
step('Для i<k интеграл ∂ᵢaᵢ по H равен нулю.','По Фубини сначала интегрируем по xᵢ∈ℝ. Компактный носитель обнуляет оба граничных значения в формуле Ньютона — Лейбница.',['y2-fubini']),
step('Интеграл ∂ₖaₖ по H равен −∫ℝᵏ⁻¹aₖ(x′,0)dx′.','По xₖ интегрируем от 0 до ∞; верхнее значение нулевое из-за компактного носителя.'),
step('На краю xₖ=0 остаётся только слагаемое (−1)ᵏ⁻¹aₖ dx₁∧…∧dxₖ₋₁.','Любой другой базисный член содержит dxₖ, который зануляется на касательных векторах края.'),
step('Индуцированная ориентация края относительно (e₁,…,eₖ₋₁) имеет знак (−1)ᵏ. Поэтому ∫∂Hω=−∫aₖ(x′,0)dx′.','Внешняя нормаль равна −eₖ; определитель базиса (−eₖ,e₁,…,eₖ₋₁) равен (−1)ᵏ. После умножения на коэффициент (−1)ᵏ⁻¹ общий знак равен −1.'),
step('Результаты третьего и пятого шагов совпадают.','Это и есть требуемое равенство. Для карты без края все координаты пробегают ℝ и обе стороны нулевые.')], 'В координатах Стокс сводится к одномерной формуле Ньютона — Лейбница и учёту ориентации.'),
proof('stokes-global','forms','Формула Стокса на компактном многообразии','Для компактного ориентированного гладкого M с краем и C¹-формы ω степени dim M−1 имеем ∫∂Mω=∫M dω.', ['M компактно, ориентировано, имеет гладкий край.','ω имеет C¹-коэффициенты до края.','Интеграл форм определён согласованными ориентированными картами.'],"Общая формула Стокса",[["forms", "Обратный образ формы"], ["forms", "Ориентация и край"], ["forms", "Цепи и интегрирование"], ["forms", "Формула Стокса в полупространстве"], ["surface", "Кратность и атлас"]],[
step('Выбираем конечное семейство ориентированных карт и гладкое разбиение единицы Σρᵢ=1, где носитель ρᵢ содержится внутри соответствующей карты.','Построение: покроем M меньшими координатными шарами с замыканиями внутри карт; компактность даёт конечное подпокрытие. В каждой карте берём гладкую неотрицательную функцию, положительную на меньшем шаре и равную нулю вне большего. Например, используется exp(−1/(1−|x|²)) внутри единичного шара и 0 снаружи. У края используем полушары; функции берём как ограничения гладких функций окружающего ℝᵏ на полупространство. Сумма bᵢ положительна на M; положим ρᵢ=bᵢ/Σbⱼ.'),
step('ω=Σρᵢω и dω=Σd(ρᵢω).','Сумма конечна, Σρᵢ=1. Внешняя производная линейна; дополнительные dρᵢ-слагаемые в сумме дают d(Σρᵢ)∧ω=0.'),
step('Для каждой формы ρᵢω применяем координатную формулу Стокса в ℝᵏ или в полупространстве.','Носитель компактен внутри области карты: за её искусственную границу перенесённую форму можно продолжить нулём без потери C¹-гладкости. У внутренних карт нет граничного вклада; у граничных остаётся именно часть ∂M. Перенос согласуется с d.',['y2-stokes-local','y2-pullback']),
step('Складываем равенства ∫M d(ρᵢω)=∫∂Mρᵢω. Получаем ∫M dω=∫∂Mω.','Линейность интегралов и сумма разбиения единицы 1 действуют также после ограничения на край.')], 'Локальные равенства согласованы ориентацией и разбиением единицы.'),
proof('green-rectangle','six','Формула Грина на прямоугольнике','На положительно ориентированной границе прямоугольника ∮P dx+Q dy=∬(∂ₓQ−∂ᵧP)dxdy.', ['P,Q∈C¹ в окрестности [a,b]×[c,d].','Положительное направление границы — против часовой стрелки.'],"Формула Грина",[["six", "Циркуляция и потенциальное поле"], ["forms", "Ориентация и край"], ["multiple", "Теорема Фубини"], ["three", "Основная теорема и формула Ньютона — Лейбница"]],[
step('Вклад P dx на горизонтальных сторонах равен ∫ₐᵇ[P(x,c)−P(x,d)]dx.','Нижняя сторона проходится слева направо, верхняя справа налево; на вертикальных dx=0.'),
step('Этот вклад равен −∫ₐᵇ∫𝒸ᵈ∂ᵧP(x,y)dydx.','Для каждого фиксированного x применяем формулу Ньютона — Лейбница к P по y.'),
step('Вклад Q dy на вертикальных сторонах равен ∫𝒸ᵈ[Q(b,y)−Q(a,y)]dy=∫𝒸ᵈ∫ₐᵇ∂ₓQ(x,y)dxdy.','Правая сторона направлена вверх, левая вниз; на горизонтальных dy=0. Затем применяем Ньютона — Лейбница по x.'),
step('Складываем вклады и приводим двойные интегралы к одному порядку.','Частные производные непрерывны на компакте и интегрируемы, поэтому Фубини разрешает перестановку.',['y2-fubini'])], 'Ориентация определяет знаки обоих граничных вкладов.', 'Для произвольной гладкой плоской области формула является частным случаем общей формулы Стокса.'),
proof('gauss-box','six','Формула Гаусса на прямоугольном параллелепипеде','Для C¹-поля F поток через границу параллелепипеда равен интегралу div F по его объёму.', ['B=[a,b]×[c,d]×[e,f].','Нормаль на границе внешняя; F=(P,Q,R) класса C¹ около B.'],"Формула Гаусса — Остроградского",[["six", "Поверхностные интегралы и поток"], ["six", "Двойной и тройной интегралы"], ["three", "Основная теорема и формула Ньютона — Лейбница"], ["multiple", "Теорема Фубини"]],[
step('Поток через грани x=b и x=a равен ∬[P(b,y,z)−P(a,y,z)]dydz.','Внешние нормали на этих гранях равны e₁ и −e₁ соответственно.'),
step('Этот поток равен ∭B∂ₓP dV.','По Ньютона — Лейбницу разность значений P есть ∫ₐᵇ∂ₓP dx; Фубини объединяет интегралы.'),
step('Аналогично пары граней y=c,d и z=e,f дают ∭B∂ᵧQ dV и ∭B∂𝓏R dV.','На каждой паре противоположных граней нормали отличаются знаком; применяется та же одномерная формула по соответствующей координате.'),
step('Сумма шести потоков равна ∭B(∂ₓP+∂ᵧQ+∂𝓏R)dV=∭B div F dV.','Поток аддитивен по граням, а объёмный интеграл линеен.')], 'Формула проверена непосредственно для параллелепипеда.', 'Общий вариант для гладкой области следует из Стокса для формы P dy∧dz+Q dz∧dx+R dx∧dy.'),
proof('fourier-convolution','fourier','Преобразование Фурье свёртки','Для f,g∈L¹(ℝⁿ) выполняется (f*g)̂(ξ)=f̂(ξ)ĝ(ξ).', ['Прямое преобразование: f̂(ξ)=∫f(x)e⁻ⁱˣ·ξdx.','f,g∈L¹.'],"Свойства преобразования Фурье",[["fourier", "Преобразование Фурье"], ["approximation", "Свёртка"], ["multiple", "Теорема Фубини"]],[
step('∫∫|f(x−y)g(y)e⁻ⁱˣ·ξ|dydx=‖f‖₁‖g‖₁<∞.','Модуль комплексной экспоненты равен 1; абсолютная интегрируемость произведения доказана в свойствах свёртки.',['y2-convolution']),
step('(f*g)̂(ξ)=∫g(y)(∫f(x−y)e⁻ⁱˣ·ξdx)dy.','Абсолютная интегрируемость разрешает Фубини и раскрытие определения свёртки.',['y2-fubini']),
step('Внутренний интеграл после замены z=x−y равен e⁻ⁱʸ·ξ∫f(z)e⁻ⁱᶻ·ξdz.','Перенос сохраняет меру, а e⁻ⁱ⁽ᶻ⁺ʸ⁾·ξ=e⁻ⁱᶻ·ξe⁻ⁱʸ·ξ.'),
step('Выносим f̂(ξ) и получаем f̂(ξ)∫g(y)e⁻ⁱʸ·ξdy=f̂(ξ)ĝ(ξ).','Фактор f̂(ξ) не зависит от y; оставшийся интеграл — определение преобразования g.')], 'В принятой нормировке дополнительного коэффициента перед произведением нет.'),
proof('riemann-lebesgue','fourier','Лемма Римана — Лебега на ℝⁿ','Для f∈L¹(ℝⁿ) имеем f̂(ξ)→0 при ‖ξ‖→∞.', ['f∈L¹(ℝⁿ).','Частота ξ вещественная; преобразование ненормированное.'],"Свойства преобразования Фурье",[["fourier", "Преобразование Фурье"], ["approximation", "Непрерывность сдвига и сглаживание"]],[
step('Для ξ≠0 положим h=πξ/‖ξ‖². Тогда h·ξ=π и h→0 при ‖ξ‖→∞.','Непосредственное вычисление скалярного произведения даёт π; норма h равна π/‖ξ‖.'),
step('Преобразование f(·+h) равно eⁱʰ·ξf̂(ξ)=−f̂(ξ).','Подстановка y=x+h в интеграл даёт множитель eⁱʰ·ξ; по выбору h он равен −1.'),
step('2|f̂(ξ)|=|(f−f(·+h))̂(ξ)|≤‖f−f(·+h)‖₁.','Линейность преобразования и оценка модуля интеграла через интеграл модуля.'),
step('Правая часть стремится к нулю по непрерывности сдвига в L¹.','Аргумент h зависит от ξ, но его норма стремится к нулю, что достаточно для нормового предела.',['y2-translation'])], 'Убывание преобразования следует из малости нормового изменения при малом сдвиге.'),
proof('fejer','fourier','Равномерная сходимость средних Фейера','Средние Фейера непрерывной 2π-периодической функции сходятся к ней равномерно.', ['f непрерывна и 2π-периодична.','σ_Nf=(S₀f+…+S_N₋₁f)/N.'],"Фейер и приближение",[["fourier", "Коэффициенты и ядро Дирихле"], ["fourier", "Комплексная запись"], ["limits", "Равномерная непрерывность и Кантор"]],[
step('Ядро среднего равно K_N(t)=|Σⱼ₌₀ᴺ⁻¹eⁱʲᵗ|²/N=(1/N)(sin(Nt/2)/sin(t/2))²≥0.','Раскрытие квадрата даёт коэффициент 1−|k|/N при частоте |k|<N — именно среднее коэффициентов частичных сумм. Геометрическая сумма даёт синусную запись.'),
step('(1/2π)∫₋π^πK_N(t)dt=1.','При интегрировании конечной суммы экспонент все ненулевые частоты исчезают; постоянный коэффициент равен 1.'),
step('Для δ≤|t|≤π имеем K_N(t)≤1/[N sin²(δ/2)], поэтому масса вне (−δ,δ) стремится к нулю.','Числитель sin²(Nt/2)≤1, а знаменатель отделён от нуля на этом множестве.'),
step('σ_Nf(x)−f(x)=(1/2π)∫K_N(t)[f(x−t)−f(x)]dt.','Представляем среднее как свёртку, а f(x) умножаем на интеграл нормированного ядра, равный 1.'),
step('На |t|<δ разность мала равномерно по x; на остальной части она ≤2max|f|, а масса ядра мала.','Непрерывность периодической функции на компакте даёт равномерную непрерывность. Сначала выбираем δ, затем N; оценка не зависит от x.')], 'Средние Фейера дают равномерное тригонометрическое приближение.'),
proof('gaussian-transform','fourier','Преобразование Фурье гауссианы','Для a>0 преобразование f(x)=e⁻ᵃˣ² равно √(π/a)e⁻ξ²/(4a).', ['Рассматривается ℝ и соглашение f̂(ξ)=∫f(x)e⁻ⁱˣξdx.','a>0.'],"Преобразование Фурье гауссианы",[["fourier", "Преобразование Фурье"], ["parameters", "Дифференцирование под интегралом"], ["parameters", "Гауссов интеграл"]],[
step('Пусть H(ξ)=∫e⁻ᵃˣ²e⁻ⁱˣξdx. Тогда H′(ξ)=−i∫x e⁻ᵃˣ²e⁻ⁱˣξdx.','Производная под интегралом мажорируется интегрируемой |x|e⁻ᵃˣ²; разностные отношения контролируются этой же функцией.'),
step('Так как f′(x)=−2axf(x), имеем H′(ξ)=(i/2a)∫f′(x)e⁻ⁱˣξdx.','Подставляем x f=−f′/(2a) в предыдущий интеграл.'),
step('По частям ∫f′e⁻ⁱˣξdx=iξH(ξ), поэтому H′(ξ)=−ξH(ξ)/(2a).','Гауссиана стремится к нулю на обоих концах, поэтому граничное слагаемое нулевое; i·i=−1.'),
step('Следовательно, производная H(ξ)e^{ξ²/(4a)} равна 0, и H(ξ)=H(0)e⁻ξ²/(4a).','Это решение полученного линейного дифференциального уравнения через интегрирующий множитель.'),
step('H(0)=∫e⁻ᵃˣ²dx=√(π/a).','Подстановка u=√a x сводит интеграл к доказанному гауссову интегралу.',['y2-gaussian'])], 'При a=1/(4t) нормированное тепловое ядро имеет преобразование e⁻ᵗξ².'),
proof('fourier-inversion-schwartz','fourier','Формула обращения для функций Шварца','Если f∈𝒮(ℝⁿ), то f(x)=(2π)⁻ⁿ∫f̂(ξ)eⁱˣ·ξdξ.', ['Все xᵅDᵝf ограничены; f гладкая.','Прямое преобразование не имеет нормировочного множителя.'],"Обращение и Планшерель",[["fourier", "Пространство Шварца"], ["fourier", "Преобразование Фурье гауссианы"], ["approximation", "Приближающая единица"], ["multiple", "Теорема Фубини"], ["lebesgue", "Теорема Лебега о мажорируемой сходимости"]],[
step('f и все её производные интегрируемы; интегрирование по частям даёт (1+‖ξ‖²)ᴺf̂(ξ)=[(1−Δ)ᴺf]̂(ξ). Поэтому f̂∈L¹ при N>n/2.','Быстрое убывание обеспечивает интегрируемость и исчезновение граничных слагаемых. Правая часть ограничена нормой L¹ соответствующей производной; функция (1+‖ξ‖²)⁻ᴺ интегрируема при 2N>n.'),
step('Для ε>0 положим I_ε(x)=(2π)⁻ⁿ∫f̂(ξ)e⁻ε‖ξ‖²eⁱˣ·ξdξ. Тогда I_ε=f*G_ε, где G_ε(z)=(4πε)⁻ⁿᐟ²e⁻‖z‖²/(4ε).','Раскрываем f̂ и применяем Фубини: двойной модуль интегрируется как ‖f‖₁∫e⁻ε‖ξ‖²dξ. Одномерная формула гауссового преобразования и разделение координат вычисляют внутренний интеграл.',['y2-fubini','y2-gaussian-transform']),
step('I_ε(x)→f(x) равномерно по x при ε↓0.','f ограниченна и равномерно непрерывна, ∫G_ε=1. Разбиваем интеграл разности на |z|<δ, где |f(x−z)−f(x)| мало, и дальний хвост, где разность ≤2‖f‖∞, а масса G_ε стремится к нулю.'),
step('С другой стороны, I_ε(x)→(2π)⁻ⁿ∫f̂(ξ)eⁱˣ·ξdξ.','Подынтегральные функции сходятся поточечно и мажорируются интегрируемой |f̂(ξ)|, установленной первым шагом. Применяется теорема Лебега.',['y2-dct']),
step('Сравнение двух пределов даёт формулу обращения в каждой точке x.','Предел числовой последовательности единственен; f непрерывна, поэтому не требуется выбирать представителя почти всюду.')], 'Формула обращения доказана для класса Шварца.', 'Общий случай f,f̂∈L¹ требует дополнительно обсуждать представителя функции и точки её восстановления; L²-версия понимается по норме.'),
proof('parseval-schwartz','fourier','Парсеваль — Планшерель для функций Шварца','Для f,g∈𝒮(ℝⁿ) выполнено ∫f·conj(g)=(2π)⁻ⁿ∫f̂·conj(ĝ); при g=f получаем равенство квадратов норм.', ['f,g — функции Шварца.','Используется та же нормировка преобразования.'],"Обращение и Планшерель",[["fourier", "Пространство Шварца"], ["fourier", "Преобразование Фурье"], ["lebesgue", "Пространства Lᵖ"], ["multiple", "Теорема Фубини"]],[
step('По обращению conj(g(x))=(2π)⁻ⁿ∫conj(ĝ(ξ))e⁻ⁱˣ·ξdξ.','Сопряжение меняет знак показателя экспоненты и проходит под абсолютно сходящийся интеграл.',['y2-fourier-inversion-schwartz']),
step('Умножаем равенство на f(x) и интегрируем по x.','f∈L¹ и g ограниченна, поэтому произведение интегрируемо.'),
step('Меняем порядок интегрирования и получаем (2π)⁻ⁿ∫conj(ĝ(ξ))(∫f(x)e⁻ⁱˣ·ξdx)dξ.','Модуль двойного интеграла не больше ‖f‖₁‖ĝ‖₁<∞; по Фубини перестановка законна.',['y2-fubini']),
step('Внутренний интеграл есть f̂(ξ); при g=f получаем ‖f‖₂²=(2π)⁻ⁿ‖f̂‖₂².','Подставляем определение преобразования, затем равенство f̂·conj(f̂)=|f̂|².')], 'Нормировка проверяется равенством квадратов L²-норм.', 'Здесь доказан результат для функций Шварца. Продолжение преобразования на всё L² строится по плотности и полноте L²; это дополнительный функционально-аналитический шаг.'),
proof('heat','fourier','Тепловое ядро решает уравнение и сохраняет массу','Для f∈L¹ и t>0 функция u(t,x)=G_t*f решает ∂ₜu=Δu, сохраняет интеграл и стремится к f в L¹ при t↓0.', ['G_t(x)=(4πt)⁻ⁿᐟ²exp(−‖x‖²/(4t)).','f∈L¹(ℝⁿ).'],"Гауссиана и уравнение теплопроводности",[["fourier", "Пространство Шварца"], ["fourier", "Преобразование Фурье гауссианы"], ["approximation", "Приближающая единица"], ["parameters", "Дифференцирование под интегралом"]],[
step('∂ₜG_t=G_t(−n/(2t)+‖x‖²/(4t²)); ΔG_t имеет то же выражение.','Непосредственно дифференцируем экспоненту и множитель t⁻ⁿᐟ² по t, затем дважды по каждой координате xᵢ.'),
step('При t в компактном подынтервале (0,∞) производные ядра ограничены по x одной конечной константой. Поэтому ∂ₜu=(∂ₜG_t)*f и Δu=(ΔG_t)*f.','Производные — полиномы по x, умноженные на гауссиану; их модули ограничены. Подынтегральные производные мажорируются C|f(y)|∈L¹, что разрешает дифференцирование.'),
step('Из первого и второго шагов следует ∂ₜu=Δu.','После переноса производных под интеграл подынтегральные ядра совпадают.'),
step('∫G_t=1, поэтому ∫u=∫f.','Гауссов интеграл вычисляет массу ядра; формула интеграла свёртки даёт её сохранение.',['y2-gaussian','y2-convolution']),
step('G_t(x)=ε⁻ⁿρ(x/ε) при ε=√t и ρ(x)=(4π)⁻ⁿᐟ²e⁻‖x‖²/4. Следовательно, ‖u(t,·)−f‖₁→0.','ρ неотрицательна, интегрируема и имеет массу 1, поэтому это приближающая единица.',['y2-approximate-identity'])], 'Уравнение выполняется при t>0, начальное условие восстанавливается по норме L¹.')
);
